INSERT INTO listings (section_id, name, category, address, phone, website, hours_default, hours_summer, hours_offseason, price_range, details, local_tip, body, verified, last_verified_at, sort, active, updated_at) VALUES ((SELECT id FROM sections WHERE city_id = (SELECT id FROM cities WHERE slug = 'outer-banks') AND type = 'tips'), 'Rip currents are real', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'The Outer Banks has some of the strongest rip currents on the East Coast. Swim near lifeguards, check the posted flags, and if caught, swim parallel to shore.', 0, NULL, 230, 1, 1762905600000);
INSERT INTO listings (section_id, name, category, address, phone, website, hours_default, hours_summer, hours_offseason, price_range, details, local_tip, body, verified, last_verified_at, sort, active, updated_at) VALUES ((SELECT id FROM sections WHERE city_id = (SELECT id FROM cities WHERE slug = 'outer-banks') AND type = 'tips'), 'Saturday traffic', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'Rental check-in day jams the Wright Memorial Bridge from late morning into the evening. Arrive early, or take the back route via US-64 if coming from the south.', 0, NULL, 240, 1, 1762905600000);
INSERT INTO listings (section_id, name, category, address, phone, website, hours_default, hours_summer, hours_offseason, price_range, details, local_tip, body, verified, last_verified_at, sort, active, updated_at) VALUES ((SELECT id FROM sections WHERE city_id = (SELECT id FROM cities WHERE slug = 'outer-banks') AND type = 'tips'), 'Mileposts are the address', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'Locals give directions by MP (milepost). The Bypass (US-158) and the Beach Road run in parallel, so MP 10 on one is close to MP 10 on the other.', 0, NULL, 250, 1, 1762905600000);
INSERT INTO listings (section_id, name, category, address, phone, website, hours_default, hours_summer, hours_offseason, price_range, details, local_tip, body, verified, last_verified_at, sort, active, updated_at) VALUES ((SELECT id FROM sections WHERE city_id = (SELECT id FROM cities WHERE slug = 'outer-banks') AND type = 'tips'), 'Sunburn weather', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'A steady ocean breeze hides how strong the sun is. Summer UV hits 9 to 10. Shade by noon, back out after 3.', 0, NULL, 260, 1, 1762905600000);
INSERT INTO listings (section_id, name, category, address, phone, website, hours_default, hours_summer, hours_offseason, price_range, details, local_tip, body, verified, last_verified_at, sort, active, updated_at) VALUES ((SELECT id FROM sections WHERE city_id = (SELECT id FROM cities WHERE slug = 'outer-banks') AND type = 'tips'), 'Storm season', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 'Hurricane season is June to November, and NC-12 can wash over in storms. Dare County may order visitors to evacuate.', 0, NULL, 270, 1, 1762905600000);
